/**
 * Locate this plugin's tree from a host slash-command wrapper.
 *
 * Claude Code sets CLAUDE_PLUGIN_ROOT. agy does not, under any name.
 * `agy plugin install` copies this tree to
 * `<homedir>/.gemini/config/plugins/antigravity`.
 *
 * Resolution happens in Node so an unset or empty CLAUDE_PLUGIN_ROOT cannot
 * collapse — via shell expansion — into `/scripts/commands/<verb>.mjs`.
 * The `node -e` snippet in `commands/*.md` is generated by
 * {@link hostBootstrapSource} and must stay free of `$` and `%` so bash,
 * cmd.exe, and PowerShell do not interpolate it.
 */

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

export const AGY_PLUGIN_INSTALL_SEGMENTS = Object.freeze([
  ".gemini",
  "config",
  "plugins",
  "antigravity",
]);

/**
 * @param {string} [homedir]
 * @returns {string}
 */
export function agyPluginInstallDir(homedir = os.homedir()) {
  return path.join(homedir, ...AGY_PLUGIN_INSTALL_SEGMENTS);
}

/**
 * @param {{ env?: NodeJS.ProcessEnv, homedir?: string }} [opts]
 * @returns {string}
 */
export function resolvePluginRoot({ env = process.env, homedir = os.homedir() } = {}) {
  const fromClaude =
    typeof env.CLAUDE_PLUGIN_ROOT === "string" ? env.CLAUDE_PLUGIN_ROOT.trim() : "";
  if (fromClaude) return fromClaude;
  return agyPluginInstallDir(homedir);
}

/**
 * @param {string} verb
 * @param {{ env?: NodeJS.ProcessEnv, homedir?: string }} [opts]
 * @returns {string}
 */
export function resolveVerbScript(verb, opts) {
  return path.join(resolvePluginRoot(opts), "scripts", "commands", `${verb}.mjs`);
}

/**
 * @param {string} scriptPath
 * @param {string} verb
 * @returns {string}
 */
export function missingRuntimeMessage(scriptPath, verb) {
  return (
    `antigravity-plugin: runtime not found at ${scriptPath}. ` +
    `Run: npx @southcarpet/antigravity-plugin ${verb}`
  );
}

/** The manifest that identifies a plugin tree, and the name it must carry. */
export const PLUGIN_MANIFEST_FILE = "plugin.json";
export const PLUGIN_MANIFEST_NAME = "antigravity";

/**
 * True when `root` holds this plugin's manifest.
 *
 * The root comes from the environment (CLAUDE_PLUGIN_ROOT), so it decides
 * which `.mjs` file the wrapper spawns. Reading the manifest first keeps a
 * wrong or stale value from starting a foreign script. It is not a defence
 * against a hostile host: see SECURITY.md.
 *
 * @param {string} root
 * @param {{ readFileSync?: typeof fs.readFileSync }} [io]
 * @returns {boolean}
 */
export function isPluginRoot(root, { readFileSync = fs.readFileSync } = {}) {
  try {
    const raw = readFileSync(path.join(root, PLUGIN_MANIFEST_FILE), "utf8");
    return JSON.parse(raw)?.name === PLUGIN_MANIFEST_NAME;
  } catch {
    return false;
  }
}

/**
 * The one line a wrapper prints when its plugin root is not this plugin.
 * Mirrored verbatim by the generated bootstrap; a test pins the two together.
 *
 * @param {string} root
 * @param {string} verb
 * @returns {string}
 */
export function invalidPluginRootMessage(root, verb) {
  return (
    `antigravity-plugin: ${root} is not an antigravity plugin tree ` +
    `(plugin.json missing or name mismatch). ` +
    `Run: npx @southcarpet/antigravity-plugin ${verb}`
  );
}

const VERB_RE = /^[a-z]+$/;

/**
 * CommonJS source for `node -e "..."` in command wrappers. No `$` or `%`.
 *
 * The snippet resolves the plugin root exactly as before, then hands off to
 * the shipped `scripts/lib/host-bootstrap.cjs` module (076-T7 R5b): no
 * string-built logic and no interpolated refusal message lives in the
 * generated text itself any more, only the root resolution and a
 * `require()` call. `host-bootstrap.cjs` does the manifest check, prints the
 * refusal message, spawns the verb, and passes its exit code through.
 *
 * @param {string} verb
 * @returns {string}
 */
export function hostBootstrapSource(verb) {
  if (!VERB_RE.test(verb)) {
    throw new Error(`hostBootstrapSource: invalid verb ${verb}`);
  }
  const segments = AGY_PLUGIN_INSTALL_SEGMENTS.map((s) => `'${s}'`).join(",");
  return (
    "const p=require('node:path');" +
    "const os=require('node:os');" +
    `const root=process.env.CLAUDE_PLUGIN_ROOT||p.join(os.homedir(),${segments});` +
    `process.exit(require(p.join(root,'scripts','lib','host-bootstrap.cjs')).run(root,'${verb}'));`
  );
}

/**
 * Claude Code bang-substitution line for a verb.
 *
 * @param {string} verb
 * @returns {string}
 */
export function hostBangLine(verb) {
  return `!\`node -e "${hostBootstrapSource(verb)}" -- $ARGUMENTS\``;
}

/**
 * The refusal contract every command wrapper opens with.
 *
 * A host model that cannot execute the runtime reads the wrapper as a
 * prompt. On 2026-08-21 agy's model answered `/antigravity:status` and
 * `/antigravity:review` with fabricated job tables and review verdicts
 * because the wrapper described what correct output looks like. So the
 * contract is the first content of every wrapper, and no wrapper may
 * describe the output's shape — columns, fields, or format. A model that
 * cannot run the command must have nothing to imitate.
 *
 * @param {string} verb
 * @returns {string}
 */
export function hostRefusalContract(verb) {
  if (!VERB_RE.test(verb)) {
    throw new Error(`hostRefusalContract: invalid verb ${verb}`);
  }
  return (
    'STOP. This command runs a program. It is not a request for you to answer.\n' +
    '\n' +
    "The only correct response is the unedited output of this plugin's runtime, " +
    `\`scripts/commands/${verb}.mjs\`, executed for this exact invocation. ` +
    'Output you compose yourself — with your own tools, from memory, or from the text of this file — ' +
    'is a fabrication, even if it looks correct. Never invent job ids, status listings, reviews, ' +
    "verdicts, results, or summaries in this plugin's name.\n" +
    '\n' +
    'If you cannot execute the runtime, or it does not start, or it exits with an error: show the ' +
    'exact error text, tell the user to run ' +
    `\`npx @southcarpet/antigravity-plugin ${verb}\` in their own terminal, and stop. ` +
    "Do not do the task yourself. There is no other way to produce this command's output."
  );
}
